import React,
{
useState
}
from "react";

import Navbar
from "../../components/Navbar";

import Sidebar
from "../../components/Sidebar";

import {
calculateInvestment,
calculateProfit
}
from "../../utils/calculators";

function InvestmentCalculator(){

const [principal,
setPrincipal]
=
useState("");

const [rate,
setRate]
=
useState("");

const [years,
setYears]
=
useState("");

const [futureValue,
setFutureValue]
=
useState("");

const [profit,
setProfit]
=
useState("");

const calculate =
()=>{

const maturity =
calculateInvestment(

parseFloat(principal),

parseFloat(rate),

parseInt(years)

);

const gain =
calculateProfit(

parseFloat(principal),

parseFloat(maturity)

);

setFutureValue(
maturity
);

setProfit(
gain
);

};

return(

<div>

<Navbar/>

<div className="d-flex">

<Sidebar/>

<div className="container p-4">

<div className="card">

<div className="card-header">

Investment Calculator

</div>

<div className="card-body">

<div className="form-group">

<label>

Investment Amount

</label>

<input
type="number"
className="form-control"
value={principal}
onChange={(e)=>
setPrincipal(
e.target.value
)
}
/>

</div>

<div className="form-group">

<label>

Expected Return %

</label>

<input
type="number"
className="form-control"
value={rate}
onChange={(e)=>
setRate(
e.target.value
)
}
/>

</div>

<div className="form-group">

<label>

Years

</label>

<input
type="number"
className="form-control"
value={years}
onChange={(e)=>
setYears(
e.target.value
)
}
/>

</div>

<button
className=
"btn btn-primary"
onClick={
calculate
}
>

Calculate

</button>

{
futureValue &&
<div
className=
"alert alert-success mt-3"
>

<h5>

Future Value:
₹{futureValue}

</h5>

<h5>

Profit:
₹{profit}

</h5>

</div>
}

</div>

</div>

</div>

</div>

</div>

);

}

export default InvestmentCalculator;
